define("local_airpay_notifications/prefs", [
    "core/ajax",
    "core/notification"
], function(Ajax, Notification) {
    "use strict";

    var collectDisabledRuleTypes = function() {
        var out = [];
        document.querySelectorAll(
            '[data-region="ap-prefs-ruletype"]:checked').forEach(function(el) {
            out.push(el.value);
        });
        return out;
    };

    var handleSubmit = function(event) {
        event.preventDefault();
        var form = event.currentTarget;
        var inapp = form.querySelector("#ap-pref-inapp").checked;
        var email = form.querySelector("#ap-pref-email").checked;
        var push = form.querySelector("#ap-pref-push").checked;
        var digest = form.querySelector("#ap-pref-digest").value;
        var qstart = parseInt(form.querySelector("#ap-pref-quiet-start").value, 10);
        var qend = parseInt(form.querySelector("#ap-pref-quiet-end").value, 10);
        var disabled_rule_types = collectDisabledRuleTypes();

        Ajax.call([{
            methodname: "local_airpay_notifications_save_prefs",
            args: {
                channel_inapp: inapp,
                channel_email: email,
                channel_push:  push,
                digest_frequency: digest,
                disabled_rule_types: disabled_rule_types,
                quiet_hours_start: qstart,
                quiet_hours_end:   qend
            }
        }])[0].then(function() {
            Notification.addNotification({
                message: "Preferences saved.",
                type: "success"
            });
            return null;
        }).catch(Notification.exception);
    };

    return {
        init: function() {
            var form = document.getElementById("ap-notif-prefs-form");
            if (!form || form.dataset.airpayInit === "1") return;
            form.dataset.airpayInit = "1";
            form.addEventListener("submit", handleSubmit);
        }
    };
});
